<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { useRouter } from 'vue-router'
import { useAuthStore } from '@/stores/auth'
import { changePassword, getOverview, type Overview } from '@/api/profile'
const router=useRouter();const auth=useAuthStore();const overview=ref<Overview>();const loading=ref(true)
onMounted(async()=>{try{overview.value=(await getOverview()).data}finally{loading.value=false}})
const cards=[['作品','workCount','/profile/works'],['活动','activityCount','/profile/activities'],['完成课时','completedLessonCount','/profile/courses'],['我的收藏','collectionCount','/profile/collections']] as const
const settingsVisible=ref(false);const savingProfile=ref(false);const savingPwd=ref(false)
const profileForm=reactive({nickname:'',phone:'',email:''});const pwdForm=reactive({oldPassword:'',newPassword:'',confirmPassword:''})
function openSettings(){Object.assign(profileForm,{nickname:auth.user?.nickname||'',phone:auth.user?.phone||'',email:auth.user?.email||''});Object.assign(pwdForm,{oldPassword:'',newPassword:'',confirmPassword:''});settingsVisible.value=true}
async function saveProfile(){if(!profileForm.nickname.trim()){ElMessage.error('请填写昵称');return}savingProfile.value=true;try{await auth.updateProfile(profileForm);ElMessage.success('资料已更新');settingsVisible.value=false}finally{savingProfile.value=false}}
async function savePassword(){if(pwdForm.newPassword.length<8||pwdForm.newPassword.length>32){ElMessage.error('新密码长度必须为 8-32 位');return}if(pwdForm.newPassword!==pwdForm.confirmPassword){ElMessage.error('两次输入的新密码不一致');return}savingPwd.value=true;try{await changePassword(pwdForm);ElMessage.success('密码已修改，请使用新密码重新登录');settingsVisible.value=false}finally{savingPwd.value=false}}
</script>
<template><main class="profile-page" v-loading="loading"><section v-if="overview" class="profile-content"><div class="profile-head"><div class="avatar">{{(auth.user?.nickname||'舞').slice(0,1)}}</div><div><p class="eyebrow">MY GROWTH</p><h1>{{auth.user?.nickname}}的成长档案</h1><p>{{overview.levelName}} · {{overview.totalPoints}} 积分</p></div><div class="head-actions"><el-button @click="openSettings">账号设置</el-button><el-button @click="router.push('/profile/points')">积分明细</el-button></div></div><section class="level"><div><span>成长进度</span><b>{{overview.levelName}}</b></div><el-progress :percentage="overview.levelProgress" :stroke-width="9" /></section><section class="stats"><button v-for="card in cards" :key="card[0]" type="button" @click="router.push(card[2])"><b>{{overview[card[1]]}}</b><span>{{card[0]}}</span></button><div><b>{{overview.receivedLikeCount}}</b><span>获得点赞</span></div></section></section><el-dialog v-model="settingsVisible" title="账号设置" width="480px"><el-tabs><el-tab-pane label="个人资料"><el-form label-position="top"><el-form-item label="昵称" required><el-input v-model="profileForm.nickname" maxlength="30" /></el-form-item><el-form-item label="手机号"><el-input v-model="profileForm.phone" maxlength="20" /></el-form-item><el-form-item label="邮箱"><el-input v-model="profileForm.email" maxlength="100" /></el-form-item><el-button type="primary" :loading="savingProfile" @click="saveProfile">保存资料</el-button></el-form></el-tab-pane><el-tab-pane label="修改密码"><el-form label-position="top"><el-form-item label="当前密码" required><el-input v-model="pwdForm.oldPassword" type="password" show-password /></el-form-item><el-form-item label="新密码（8-32 位）" required><el-input v-model="pwdForm.newPassword" type="password" show-password /></el-form-item><el-form-item label="确认新密码" required><el-input v-model="pwdForm.confirmPassword" type="password" show-password /></el-form-item><el-button type="primary" :loading="savingPwd" @click="savePassword">修改密码</el-button></el-form></el-tab-pane></el-tabs></el-dialog></main></template>
<style scoped>.profile-page{min-height:100vh;padding:58px 24px;color:#fff}.profile-content{max-width:1040px;margin:auto}.profile-head{display:flex;align-items:center;gap:18px}.avatar{display:grid;place-items:center;width:74px;height:74px;border-radius:50%;background:linear-gradient(135deg,#b92bd1,#ef9afa);font-size:30px}.profile-head h1{margin:5px 0;font-size:36px}.profile-head p{margin:0;color:rgba(255,255,255,.7)}.head-actions{margin-left:auto;display:flex;gap:10px}.eyebrow{color:#f0a8fb!important;font-size:12px;letter-spacing:2px}.level{margin:38px 0 22px;padding:22px;border:1px solid rgba(244,205,250,.24);border-radius:10px;background:rgba(54,12,70,.8)}.level div{display:flex;justify-content:space-between;margin-bottom:16px}.level span{color:rgba(255,255,255,.68)}.level b{color:#f0a8fb}.stats{display:grid;grid-template-columns:repeat(5,1fr);gap:14px}.stats button,.stats>div{display:grid;gap:8px;padding:20px;border:1px solid rgba(244,205,250,.24);border-radius:10px;background:rgba(54,12,70,.8);color:#fff;text-align:left}.stats button{cursor:pointer}.stats b{font-size:28px}.stats span{color:rgba(255,255,255,.65);font-size:13px}@media(max-width:760px){.stats{grid-template-columns:repeat(2,1fr)}.profile-head{align-items:start;flex-wrap:wrap}.head-actions{margin-left:92px}}</style>
